import{c as a,Q as e,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Code チームの働き方変化：監督から方向づけへ","description":"","frontmatter":{"url":"https://x.com/AI_masaou/status/2064448218038223206","title":"Claude Code チームの働き方変化：監督から方向づけへ","author":"まさお@AI駆動開発","archived":"2026-06-13T00:00:00.000Z","handle":"@AI_masaou","published":"2026-06-09T00:00:00.000Z","stats":"98 likes · 19 retweets · 72 bookmarks · 23221 views","tags":["claude-fable-5","claude-code-team","workflow-shift","goal-prompt","context-over-constraints","thariq"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-09-@AI_masaou-223206.md","filePath":"research/tweets/2026-06-09-@AI_masaou-223206.md","lastUpdated":1785909234000}'),d={name:"research/tweets/2026-06-09-@AI_masaou-223206.md"};function l(s,t,i,n,h,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="claude-code-チームの働き方変化-監督から方向づけへ-—-ai-masaou" tabindex="-1">Claude Code チームの働き方変化：監督から方向づけへ — @AI_masaou <a class="header-anchor" href="#claude-code-チームの働き方変化-監督から方向づけへ-—-ai-masaou" aria-label="Permalink to &quot;Claude Code チームの働き方変化：監督から方向づけへ — @AI_masaou&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/AI_masaou/status/2064448218038223206" target="_blank" rel="noreferrer">https://x.com/AI_masaou/status/2064448218038223206</a><strong>作者</strong>：まさお@AI駆動開発（@AI_masaou） <strong>發布日期</strong>：2026-06-09 <strong>收錄日期</strong>：2026-06-13 <strong>類型</strong>：Tweet <strong>統計</strong>：98 likes · 19 retweets · 72 bookmarks · 23221 views</p><blockquote><p>Quote @ClaudeDevs: Claude Fable 5 changed how we work on the Claude Code team day to day. We used to verify that Claude did the work right. Now we verify that it&#39;s doing the right work. Here&#39;s the 3 biggest changes:</p></blockquote><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude Fable 5で変わった、Claude Codeチームの日々の働き方が面白い</p><p>✔︎ Claude CodeチームのThariqは、Claude Fable 5によってAnthropic内でのClaudeとの向き合い方が大きく変わったと話している。</p><p>以前は、Claudeが「作業を正しくできているか」を人間が細かく確認する必要があった。タスクを小さく分け、出力を確認し、途中で止まっていないかを見る、という監督に近い使い方だった</p><p>しかしFable 5では、長時間の作業、自分でのテスト、質の高いコード生成ができるようになり、</p><p>人間の役割は「正しく作業しているかの監視」から「正しい作業に向かっているかの方向づけ」へ移っている。 つまり、監督よりも、目的設定や文脈づくりが重要になった。</p><p>変化した働き方は大きく3つある。</p><h3 id="_1-claudeを思考のパートナーとして使う" tabindex="-1">1. Claudeを思考のパートナーとして使う <a class="header-anchor" href="#_1-claudeを思考のパートナーとして使う" aria-label="Permalink to &quot;1. Claudeを思考のパートナーとして使う&quot;">​</a></h3><p>実装に入る前からClaudeを巻き込み、自分が何を作りたいのか、何が可能なのかを一緒に整理する。小さな仕様を書いてClaudeに質問させたり、アイデアから複数の方向性やHTMLモックを作らせたりすることで、実装前に曖昧さや問題点に気づける。</p><h3 id="_2-制約ではなく文脈を渡す" tabindex="-1">2. 制約ではなく文脈を渡す <a class="header-anchor" href="#_2-制約ではなく文脈を渡す" aria-label="Permalink to &quot;2. 制約ではなく文脈を渡す&quot;">​</a></h3><p>「シンプルにして」「作り込みすぎないで」といった抽象的な指示だけでなく、なぜそうしてほしいのかを伝える。たとえば「この機能は実験で、1か月後に消す可能性がある。だから捨てづらい構造にはしないで」と伝えると、Claudeは目的に合った判断をしやすくなる。</p><h3 id="_3-ゴールと検証方法を与える" tabindex="-1">3. ゴールと検証方法を与える <a class="header-anchor" href="#_3-ゴールと検証方法を与える" aria-label="Permalink to &quot;3. ゴールと検証方法を与える&quot;">​</a></h3><p>Fable 5には、完了まで作業を続けるための「/goal」と、作業を検証するための「Workflows」が有効だと紹介されている。仕様を渡し、完全実装をゴールとして設定し、各ステップをワークフローで検証させることで、Claudeの能力を活かしつつ、望んだものが作られているか確認できる。</p><p>最後に、Thariqは「もっと野心的に使ってみてほしい」と話している。</p><p>Fable 5は、これまでLLMには難しいと思っていた作業にも挑戦する価値があるモデルであり、実際にこの動画編集もFableで行っているという。 Claude Fable 5は、Claude Codeでできることの水準を引き上げるものだ、というのが動画全体のメッセージだろう</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Anthropic Claude Code チーム Thariq の影片摘要（日文）——Fable 5 後人間角色從「監督作業正確性」轉為「引導方向正確性」；三大變化：思考夥伴、脈絡優先於限制、目標+驗證。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>角色轉變</strong>：「正しく作業しているか → 正しい作業に向かっているか」（verify work is done right → verify doing the right work）——從 supervisor 到 director</li><li><strong>思考夥伴</strong>：實作前先讓 Claude 協助釐清需求、探索方向、製作 HTML mock——對應 IDENTIFY 階段</li><li><strong>脈絡 &gt; 限制</strong>：「這是實驗功能，一個月後可能刪除，所以不要建構難以拋棄的結構」比「保持簡單」更有效——給 WHY 而非 WHAT</li><li><strong>Goal + Workflows</strong>：<code>/goal</code> 設定完成條件 + Workflows 逐步驗證 = 結構化的 loop</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>來源：ClaudeDevs（Thariq，Claude Code 團隊成員）官方影片</li><li>工具：<code>/goal</code>（長任務完成條件）、Workflows（逐步驗證）</li><li>Fable 5 用於該影片本身的編輯</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>「Context &gt; Constraints」直接對應 core.md IDENTIFY</strong>：「なぜそうしてほしいのかを伝える」= 我們的「詮釋 ≤2 句，非複述」+ 關鍵假設列舉；抽象指示（「シンプルにして」）= 弱成功條件</li><li><strong>Supervisor → Director 轉變是 Loop Engineering 的本質</strong>：從逐步監督到目標設定 + 驗證 = 從 prompt engineering 到 harness engineering 的跨越——與 bibryam 的五階段演進（2026-06-12 歸檔）一致</li><li><strong>官方一手資訊</strong>：作為 Anthropic 內部人員的 workflow 分享，可信度高；但經日文推主二手轉述，可能有遺漏或詮釋偏差</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>「脈絡 &gt; 限制」可強化 IDENTIFY 階段指引；/goal + Workflows 的使用範式可參考</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>Supervisor→Director 轉變已被多人提及；但 Anthropic 官方視角增加權威性</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>來自 Claude Code 團隊成員一手經驗；但為影片二手轉述，非原始影片</td></tr><tr><td>D. 技術深度 (15%)</td><td>4/10</td><td>工作方式哲學為主，技術細節有限（/goal + Workflows 僅點到）</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>「從監督到方向」的思維轉變適用任何 AI-assisted 開發</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.95/10</strong></td><td>7×0.3+5×0.2+6×0.2+4×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：「Context &gt; Constraints」原則可強化 core.md IDENTIFY 階段的指引——給 WHY（脈絡）比給 WHAT（限制）更有效；Anthropic 官方 workflow shift 佐證 harness-first 方向</p>',32)])])}const p=a(d,[["render",l]]);export{g as __pageData,p as default};
